<script setup>
import { computed, onBeforeUnmount, reactive, ref, watchEffect } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ChatDotRound, DocumentChecked, House, User } from '@element-plus/icons-vue'

const router = useRouter()
const route = useRoute()
const currentPage = ref('home')
const activeFormTab = ref('base')
const firstArchiveView = ref('list')
const activeArchiveIndex = ref(0)
const firstArchiveMessage = ref('')
const changeDialogVisible = ref(false)
const sendConfirmVisible = ref(false)
const changeReason = ref('')
const dailyMessage = ref('')
const dailyChangeDialogVisible = ref(false)
const dailySendConfirmVisible = ref(false)
const dailyChangeReason = ref('')
const photoPreview = reactive({ visible: false, baby: null, index: 0 })
const photoAction = reactive({ visible: false, baby: null, index: 0 })
const photoDeleteConfirm = reactive({ visible: false, baby: null, index: 0 })
const collapsedBabies = ref({})
const motherCollapsed = ref(false)

const order = {
  no: 'DD202608060001',
  staff: '张洪霞',
  customer: '王女士',
  baby: '出生13天',
  serviceType: '月嫂服务',
  serviceDay: 13,
  status: '服务中',
  period: '2026-08-01 至 2026-08-14',
  startDate: '2026-08-01',
  phone: '13800008888',
}

function createBaby(name = '小雨', gender = '女') {
  return {
    name, gender, birthDate: '2026-07-31', advicePhotos: ['出院医嘱1.jpg'], temperature: '36.8',
    jaundice: '有', jaundiceValue: '5.8', jaundiceTrend: '消退', scalpMass: '无', eyeAppearance: '正常', eyeDischarge: '无', earAppearance: '正常', earDischarge: '无', noseAppearance: '正常', noseDischarge: '无', oralAppearance: '正常', thrush: '无', faceNote: '', breast: '正常', cord: '未脱落', cordDischarge: ['无'], cordAppearance: ['干燥'], genital: '正常', spine: '无', trunkNote: '', limbsNormal: '是', limbsNote: '', skinType: '正常', rashPositions: [], rashSymptoms: [], rashTrend: '', birthmarkPosition: '', skinNote: '',
  }
}
function createArchive(staff = order.staff, status = '草稿', date = order.startDate) {
  return {
    staff,
    arriveDate: date,
    status,
    filledAt: ['已提交', '已发送'].includes(status) ? `${date} 09:18` : '',
    requestReason: '',
    requestTime: '',
    rejectReason: '',
    version: ['已提交', '已发送'].includes(status) ? 1 : 0,
    history: ['已提交', '已发送'].includes(status) ? [{ version: 'V1', type: '初次发送', operator: staff, time: `${date} 09:18`, reason: '到岗当日基础情况记录发送到公司', before: '待填写', after: '已发送' }] : [],
    babyCountType: '单胎',
    babies: [createBaby()],
    mother: { temperature: '36.6', diseases: ['无'], diseaseOther: '', infections: ['无'], infectionOther: '', breast: '正常', nipple: '正常', cesareanWound: '未知', perinealWound: ['正常'], lochiaAmount: '少', lochiaColor: '暗红', lochiaSmell: '无异味' },
  }
}

const firstArchives = reactive([createArchive('张洪霞', '草稿', '2026-08-01'), createArchive('李小红', '待填写', '2026-08-05')])
const activeArchive = computed(() => firstArchives[activeArchiveIndex.value])
const editableArchive = computed(() => ['待填写', '草稿', '可修改'].includes(activeArchive.value?.status))
const readonlyArchive = computed(() => !editableArchive.value)
const activeArchiveModeText = computed(() => readonlyArchive.value ? '查看' : '编辑')
const canSubmitFirstArchive = computed(() => {
  const archive = activeArchive.value
  if (!archive || readonlyArchive.value) return false
  const missingBaby = archive.babies.some((baby) => !baby.name || !baby.gender || !baby.birthDate || !baby.temperature || !baby.advicePhotos.length || (baby.jaundice === '有' && (!baby.jaundiceValue || !baby.jaundiceTrend)) || (baby.cord === '未脱落' && (!baby.cordDischarge.length || !baby.cordAppearance.length)))
  const mother = archive.mother
  const missingMother = !mother.temperature || !mother.diseases.length || !mother.infections.length || !mother.breast || !mother.nipple || !mother.cesareanWound || !mother.perinealWound.length || !mother.lochiaAmount || !mother.lochiaColor || !mother.lochiaSmell
  return !missingBaby && !missingMother
})
const isMobilePreview = computed(() => route.query.preview === 'mobile')
watchEffect(() => {
  document.body.classList.toggle('nursing-mobile-preview', isMobilePreview.value)
})
onBeforeUnmount(() => {
  document.body.classList.remove('nursing-mobile-preview')
})

const bottomTabs = [{ key: 'home', label: '首页', icon: House }, { key: 'service', label: '服务', icon: DocumentChecked }, { key: 'message', label: '消息', icon: ChatDotRound }, { key: 'mine', label: '我的', icon: User }]
const quickEntries = ['每日服务记录', '到岗当日基础情况记录', '历史服务记录', '服务提醒', '宣教培训']
const serviceItems = computed(() => [
  { title: '到岗当日基础情况记录', text: `${firstArchives.length}条记录 · ${firstArchives.filter((item) => ['待填写', '草稿'].includes(item.status)).length}条待处理`, action: '进入管理' },
  { title: '每日服务记录', text: '今日记录、事件列表和多次新增事件', action: '进入记录' },
  { title: '历史服务记录', text: '查看最近服务记录列表', action: '查看历史' },
])
const messages = [{ type: '系统提醒', text: '今日服务记录未填写', time: '09:20' }, { type: '系统提醒', text: '请完成结束打卡', time: '18:00' }, { type: '异常提醒', text: '宝宝体温异常，请关注', time: '昨天' }, { type: '培训宣教', text: '新生儿护理知识', time: '07-12' }]
const formTabs = [{ key: 'base', label: '基础信息' }, { key: 'mother', label: '妈妈情况' }, { key: 'baby', label: '宝宝情况' }]
const logs = Array.from({ length: 7 }, (_, index) => { const day = 13 - index; return { id: index + 1, date: `2026-08-${String(day).padStart(2, '0')}`, babyAge: day, serviceDay: day, status: index === 0 ? '待填写' : '已完成', staff: order.staff, customer: order.customer } })
const events = [{ type: '喂奶记录', text: '08:30 母乳 80ml' }, { type: '排便记录', text: '12:40 黄色糊状，中等量' }, { type: '睡眠记录', text: '14:00-16:10 睡眠稳定' }, { type: '洗澡记录', text: '17:30 水温合适，皮肤正常' }, { type: '护理记录', text: '脐部护理完成，无红肿' }]
const dailyRecord = reactive({
  date: '2026-08-13',
  status: '草稿',
  version: 0,
  filledAt: '',
  requestReason: '',
  requestTime: '',
  rejectReason: '',
  history: [],
  base: { serviceDay: '13', babyAge: '13', roomTemp: '26', humidity: '55', nurseHealth: '良好', note: '宝宝吃奶规律，宝妈状态稳定' },
  mother: { temperature: '36.6', mood: '愉悦', breast: '正常', lochia: '少，无异味', sleep: '中', diet: '好' },
  baby: { temperature: '36.8', weight: '3.8', jaundice: '轻度消退', skin: '正常', stoolCount: '4', sleepHours: '16' },
})
const pageTitle = computed(() => ({ home: '家政服务移动端', service: '服务', message: '消息', mine: '我的', daily: '每日服务记录', history: '历史服务记录', first: '到岗当日基础情况记录' }[currentPage.value] || '家政服务移动端'))
const showBack = computed(() => ['daily', 'history', 'first'].includes(currentPage.value))
const activeBottomTab = computed(() => ['daily', 'history', 'first'].includes(currentPage.value) ? 'service' : currentPage.value)
const editableDailyRecord = computed(() => ['待填写', '草稿', '可修改'].includes(dailyRecord.status))
const readonlyDailyRecord = computed(() => !editableDailyRecord.value)
const dailyStatusTitle = computed(() => dailyRecord.status === '修改申请中' ? '审核中' : dailyRecord.status === '可修改' ? '可修改' : dailyRecord.status === '修改申请驳回' || dailyRecord.status === '修改驳回' ? '修改申请驳回' : '已发送锁定')
const dailyStatusText = computed(() => {
  if (dailyRecord.status === '修改申请中') return '修改申请审核中，管理员审核前不可继续编辑'
  if (dailyRecord.status === '可修改') return '管理员已通过修改申请，可重新编辑记录'
  if (dailyRecord.status === '修改申请驳回' || dailyRecord.status === '修改驳回') return '修改申请已驳回，记录保持锁定'
  return '记录已发送到公司，当前不可直接修改'
})
const baseFields = computed(() => [['记录日期', dailyRecord.date], ['服务第几天', dailyRecord.base.serviceDay], ['宝宝出生第几天', dailyRecord.base.babyAge], ['环境情况', `室温${dailyRecord.base.roomTemp}℃，湿度${dailyRecord.base.humidity}%`], ['护理师健康', dailyRecord.base.nurseHealth], ['其他备注', dailyRecord.base.note]])
const motherFields = computed(() => [['妈妈体温', `${dailyRecord.mother.temperature}℃`], ['精神状态', dailyRecord.mother.mood], ['乳房情况', dailyRecord.mother.breast], ['恶露情况', dailyRecord.mother.lochia], ['睡眠情况', dailyRecord.mother.sleep], ['饮食情况', dailyRecord.mother.diet]])
const babyFields = computed(() => [['宝宝体温', `${dailyRecord.baby.temperature}℃`], ['体重', `${dailyRecord.baby.weight}kg`], ['黄疸变化', dailyRecord.baby.jaundice], ['皮肤状态', dailyRecord.baby.skin], ['排便次数', `${dailyRecord.baby.stoolCount}次`], ['睡眠情况', `约${dailyRecord.baby.sleepHours}小时`]])

function openQuickEntry(label) { if (label === '每日服务记录') currentPage.value = 'daily'; if (label === '到岗当日基础情况记录') { currentPage.value = 'first'; firstArchiveView.value = 'list' } if (label === '历史服务记录') currentPage.value = 'history'; if (label === '服务提醒') currentPage.value = 'message' }
function switchBottomTab(key) { currentPage.value = key }
function openService(item) { if (item.title === '每日服务记录') currentPage.value = 'daily'; if (item.title === '历史服务记录') currentPage.value = 'history'; if (item.title === '到岗当日基础情况记录') { currentPage.value = 'first'; firstArchiveView.value = 'list' } }
function goBack() { if (currentPage.value === 'first' && firstArchiveView.value === 'edit') { firstArchiveView.value = 'list'; return } if (showBack.value) { currentPage.value = 'service'; return } router.push('/') }
function updateRadio(target, key, value) { if (!readonlyArchive.value) target[key] = value }
function updateDailyRadio(target, key, value) { if (!readonlyDailyRecord.value) target[key] = value }
function updateCheckbox(target, key, value, checked) {
  if (readonlyArchive.value) return
  if (value === '无' || value === '正常') { target[key] = checked ? [value] : []; return }
  const base = target[key].filter((item) => item !== '无' && item !== '正常')
  target[key] = checked ? [...base, value] : base.filter((item) => item !== value)
}
function setBabyCount(type) { if (readonlyArchive.value) return; activeArchive.value.babyCountType = type; if (type === '多胎' && activeArchive.value.babies.length === 1) activeArchive.value.babies.push(createBaby('小云', '男')); if (type === '单胎') activeArchive.value.babies.splice(1) }
function setBabyTotal(total) { if (readonlyArchive.value) return; const count = Math.max(2, Math.min(5, Number(total) || 2)); activeArchive.value.babyCountType = '多胎'; while (activeArchive.value.babies.length < count) activeArchive.value.babies.push(createBaby(`小宝${activeArchive.value.babies.length + 1}`, activeArchive.value.babies.length % 2 ? '男' : '女')); activeArchive.value.babies.splice(count) }
function addAdvicePhoto(baby) { if (!readonlyArchive.value) baby.advicePhotos.push(`出院医嘱${baby.advicePhotos.length + 1}.jpg`) }
function openPhotoAction(baby, index) {
  photoAction.visible = true
  photoAction.baby = baby
  photoAction.index = index
}
function openPhotoPreview(baby = photoAction.baby, index = photoAction.index) {
  if (!baby?.advicePhotos?.length) return
  photoPreview.visible = true
  photoPreview.baby = baby
  photoPreview.index = Math.max(0, Math.min(index, baby.advicePhotos.length - 1))
  photoAction.visible = false
}
function switchPhoto(offset) {
  const photos = photoPreview.baby?.advicePhotos || []
  if (!photos.length) return
  photoPreview.index = (photoPreview.index + offset + photos.length) % photos.length
}
function askDeletePhoto() {
  photoDeleteConfirm.visible = true
  photoDeleteConfirm.baby = photoAction.baby
  photoDeleteConfirm.index = photoAction.index
  photoAction.visible = false
}
function confirmDeletePhoto() {
  if (readonlyArchive.value) return
  photoDeleteConfirm.baby?.advicePhotos.splice(photoDeleteConfirm.index, 1)
  photoDeleteConfirm.visible = false
  firstArchiveMessage.value = '图片已删除'
}
function addArchive() { const exists = firstArchives.some((item) => item.staff === order.staff); if (exists) { firstArchiveMessage.value = '当前服务员已存在到岗当日基础情况记录，不允许重复创建'; return } firstArchives.unshift(createArchive(order.staff, '待填写', order.startDate)); activeArchiveIndex.value = 0; firstArchiveView.value = 'edit'; firstArchiveMessage.value = '' }
function openArchive(index) { activeArchiveIndex.value = index; firstArchiveView.value = 'edit'; firstArchiveMessage.value = ''; collapsedBabies.value = {}; motherCollapsed.value = false }
function toggleBaby(index) { collapsedBabies.value = { ...collapsedBabies.value, [index]: !collapsedBabies.value[index] } }
function toggleMother() { motherCollapsed.value = !motherCollapsed.value }
function saveFirstDraft() { if (readonlyArchive.value) return; activeArchive.value.status = '草稿'; firstArchiveMessage.value = '保存成功，未发送到公司' }
function submitFirstArchive() {
  if (readonlyArchive.value) return
  const archive = activeArchive.value
  const missingBaby = archive.babies.some((baby) => !baby.name || !baby.gender || !baby.birthDate || !baby.temperature || !baby.advicePhotos.length || (baby.jaundice === '有' && (!baby.jaundiceValue || !baby.jaundiceTrend)) || (baby.cord === '未脱落' && (!baby.cordDischarge.length || !baby.cordAppearance.length)))
  const mother = archive.mother
  const missingMother = !mother.temperature || !mother.diseases.length || !mother.infections.length || !mother.breast || !mother.nipple || !mother.cesareanWound || !mother.perinealWound.length || !mother.lochiaAmount || !mother.lochiaColor || !mother.lochiaSmell
  if (missingBaby || missingMother) { firstArchiveMessage.value = '请补全必填项后再发送'; return }
  sendConfirmVisible.value = true
  firstArchiveMessage.value = ''
}
function confirmSendFirstArchive() {
  if (readonlyArchive.value) return
  const archive = activeArchive.value
  const nextVersion = archive.version + 1
  archive.version = nextVersion
  archive.history.push({ version: `V${nextVersion}`, type: nextVersion === 1 ? '初次发送' : '修改后发送', operator: archive.staff, time: '2026-08-01 09:18', reason: archive.requestReason || '到岗当日基础情况记录发送到公司', before: nextVersion === 1 ? '待填写' : '可修改', after: '已发送' })
  archive.status = '已发送'; archive.filledAt = '2026-08-01 09:18'; archive.rejectReason = ''; sendConfirmVisible.value = false; firstArchiveMessage.value = '已发送到公司，记录暂不可直接修改'
}
function openChangeDialog() {
  changeReason.value = activeArchive.value?.requestReason || 'Mock申请修改：演示继续编辑到岗当日基础情况记录'
  changeDialogVisible.value = true
  firstArchiveMessage.value = ''
}
function submitChangeRequest() {
  const archive = activeArchive.value
  const beforeStatus = archive.status
  archive.requestReason = changeReason.value.trim() || 'Mock申请修改：演示继续编辑到岗当日基础情况记录'
  archive.requestTime = '2026-08-01 10:30'
  archive.rejectReason = ''
  archive.history.push({ version: `V${archive.version}`, type: '申请修改', operator: archive.staff, time: archive.requestTime, reason: archive.requestReason, before: beforeStatus, after: '修改申请中' })
  archive.status = '可修改'
  archive.history.push({ version: `V${archive.version + 1}`, type: 'Mock审核通过', operator: '系统Mock', time: '2026-08-01 10:31', reason: archive.requestReason, before: '修改申请中', after: '可修改' })
  changeDialogVisible.value = false
  firstArchiveMessage.value = '修改申请已通过，可继续修改记录'
}
function simulateApproveChange() {
  const archive = activeArchive.value
  archive.status = '可修改'
  archive.history.push({ version: `V${archive.version + 1}`, type: '审核通过', operator: '管理员', time: '2026-08-01 11:10', reason: archive.requestReason, before: '修改申请中', after: '可修改' })
  firstArchiveMessage.value = '管理员已通过修改申请，可重新编辑记录'
}
function simulateRejectChange() {
  const archive = activeArchive.value
  archive.status = '修改申请驳回'
  archive.rejectReason = '请补充出生证明后重新发起申请'
  archive.history.push({ version: `V${archive.version}`, type: '审核驳回', operator: '管理员', time: '2026-08-01 11:10', reason: archive.rejectReason, before: '修改申请中', after: '修改申请驳回' })
  firstArchiveMessage.value = '修改申请已拒绝'
}
function saveDailyDraft() {
  if (readonlyDailyRecord.value) return
  dailyRecord.status = '草稿'
  dailyMessage.value = '保存成功，未发送到公司'
}
function submitDailyRecord() {
  if (readonlyDailyRecord.value) return
  dailySendConfirmVisible.value = true
  dailyMessage.value = ''
}
function confirmSendDailyRecord() {
  if (readonlyDailyRecord.value) return
  const nextVersion = dailyRecord.version + 1
  dailyRecord.version = nextVersion
  dailyRecord.filledAt = '2026-08-13 18:20'
  dailyRecord.history.push({ version: `V${nextVersion}`, type: nextVersion === 1 ? '初次发送' : '修改后发送', operator: order.staff, time: dailyRecord.filledAt, reason: dailyRecord.requestReason || '每日服务记录发送到公司', before: nextVersion === 1 ? '草稿' : '可修改', after: '已发送' })
  dailyRecord.status = '已发送'
  dailyRecord.rejectReason = ''
  dailySendConfirmVisible.value = false
  dailyMessage.value = '已发送到公司，记录暂不可直接修改'
}
function openDailyChangeDialog() {
  dailyChangeReason.value = dailyRecord.requestReason || 'Mock申请修改：演示继续编辑每日服务记录'
  dailyChangeDialogVisible.value = true
  dailyMessage.value = ''
}
function submitDailyChangeRequest() {
  const beforeStatus = dailyRecord.status
  dailyRecord.requestReason = dailyChangeReason.value.trim() || 'Mock申请修改：演示继续编辑每日服务记录'
  dailyRecord.requestTime = '2026-08-13 19:00'
  dailyRecord.rejectReason = ''
  dailyRecord.history.push({ version: `V${dailyRecord.version}`, type: '申请修改', operator: order.staff, time: dailyRecord.requestTime, reason: dailyRecord.requestReason, before: beforeStatus, after: '修改申请中' })
  dailyRecord.status = '可修改'
  dailyRecord.history.push({ version: `V${dailyRecord.version + 1}`, type: 'Mock审核通过', operator: '系统Mock', time: '2026-08-13 19:01', reason: dailyRecord.requestReason, before: '修改申请中', after: '可修改' })
  dailyChangeDialogVisible.value = false
  dailyMessage.value = '修改申请已通过，可继续修改记录'
}
</script>

<template>
  <main class="miniapp-page" :class="{ 'mobile-preview': isMobilePreview }">
    <section class="phone">
      <header class="wx-nav">
        <button type="button" class="back-btn" @click="goBack">‹</button>
        <strong>{{ pageTitle }}</strong>
        <span class="nav-spacer"></span>
      </header>
      <div class="content">
        <template v-if="currentPage === 'home'">
          <section class="order-card">
            <p>当前服务订单</p>
            <h1>{{ order.customer }}</h1>
            <div class="read-list on-primary">
              <div><span>订单编号</span><strong>{{ order.no }}</strong></div>
              <div><span>服务类型</span><strong>{{ order.serviceType }}</strong></div>
              <div><span>服务周期</span><strong>{{ order.serviceDay }}天</strong></div>
              <div><span>服务状态</span><strong>{{ order.status }}</strong></div>
              <div><span>当前服务员</span><strong>{{ order.staff }}</strong></div>
            </div>
          </section>
          <section class="clock-card"><div><strong>今日打卡</strong><em class="tag ok">{{ order.status }}</em></div><p>开始服务时间：08:30</p><p>结束服务时间：未打卡</p><button type="button">结束打卡</button></section>
          <section class="task-card"><h2>今日任务</h2><label><input type="checkbox">今日服务记录</label><label><input type="checkbox">宝宝情况记录</label><label><input type="checkbox">妈妈情况记录</label></section>
          <section class="quick-grid"><button v-for="item in quickEntries" :key="item" type="button" @click="openQuickEntry(item)"><span>{{ item.slice(0, 1) }}</span><strong>{{ item }}</strong></button></section>
        </template>

        <template v-else-if="currentPage === 'service'">
          <button v-for="item in serviceItems" :key="item.title" class="service-item" type="button" @click="openService(item)"><div><strong>{{ item.title }}</strong><span>{{ item.text }}</span></div><em>{{ item.action }}</em></button>
        </template>

        <template v-else-if="currentPage === 'daily'">
          <section v-if="readonlyDailyRecord" class="record-status-tip">
            <div><strong>{{ dailyStatusTitle }}</strong><p>{{ dailyStatusText }}</p><span v-if="dailyRecord.rejectReason">拒绝原因：{{ dailyRecord.rejectReason }}</span></div>
            <button v-if="dailyRecord.status === '已发送' || dailyRecord.status === '已提交' || dailyRecord.status === '修改申请驳回' || dailyRecord.status === '修改驳回'" type="button" @click="openDailyChangeDialog">申请修改</button>
          </section>
          <section class="archive-card business-section order-info-card"><div class="module-title"><i></i><strong>订单信息</strong><em :class="['tag', dailyRecord.status === '草稿' || dailyRecord.status === '待填写' ? 'draft' : dailyRecord.status.includes('申请') ? 'pending' : 'ok']">{{ dailyRecord.status }}</em></div><div class="inline-info arrival-order-info"><div><span>宝妈：</span><strong>{{ order.customer }}</strong></div><div><span>当前服务员：</span><strong>{{ order.staff }}</strong></div><div class="wide"><span>订单编号：</span><strong>{{ order.no }}</strong></div><div class="wide"><span>服务周期：</span><strong>{{ order.period }}</strong></div></div></section>
          <section class="archive-card business-section daily-record-card"><div class="module-title"><i></i><strong>今日记录</strong><span>{{ readonlyDailyRecord ? '查看' : '编辑' }}</span></div><nav class="form-tabs"><button v-for="tab in formTabs" :key="tab.key" :class="{ active: activeFormTab === tab.key }" type="button" @click="activeFormTab = tab.key">{{ tab.label }}</button></nav><template v-if="readonlyDailyRecord"><div class="archive-read-grid"><p v-for="field in activeFormTab === 'base' ? baseFields : activeFormTab === 'mother' ? motherFields : babyFields" :key="field[0]" :class="{ 'archive-read-wide': field[0] === '其他备注' || field[0] === '环境情况' }"><span>{{ field[0] }}：</span><strong>{{ field[1] }}</strong></p></div></template><template v-else>
            <div v-if="activeFormTab === 'base'"><div class="form-field"><span class="required">记录日期</span><input v-model="dailyRecord.date" type="date"></div><div class="form-field"><span class="required">服务第几天</span><input v-model="dailyRecord.base.serviceDay" type="number" inputmode="numeric"></div><div class="form-field"><span class="required">宝宝出生第几天</span><input v-model="dailyRecord.base.babyAge" type="number" inputmode="numeric"></div><div class="sub-fields daily-env-fields"><div class="inline-field"><span class="field-label">室温</span><input v-model="dailyRecord.base.roomTemp" class="short-input" type="number" inputmode="decimal"><em>℃</em></div><div class="inline-field"><span class="field-label">湿度</span><input v-model="dailyRecord.base.humidity" class="short-input" type="number" inputmode="decimal"><em>%</em></div></div><div class="form-field"><span class="field-label">护理师健康</span><div class="radio-row"><label v-for="item in ['良好','感冒','发热','其他']" :key="item"><input type="radio" name="daily-nurse-health" :checked="dailyRecord.base.nurseHealth === item" @change="updateDailyRadio(dailyRecord.base,'nurseHealth',item)">{{ item }}</label></div></div><div class="form-field daily-text-field"><span class="field-label">其他备注</span><textarea v-model="dailyRecord.base.note" rows="3" placeholder="填写当天特殊情况或交接备注"></textarea></div></div>
            <div v-else-if="activeFormTab === 'mother'"><div class="form-field"><span class="field-label">妈妈体温</span><input v-model="dailyRecord.mother.temperature" type="number" inputmode="decimal" placeholder="℃"></div><div class="form-field"><span class="field-label">精神状态</span><div class="radio-row"><label v-for="item in ['愉悦','平稳','疲惫','焦虑']" :key="item"><input type="radio" name="daily-mother-mood" :checked="dailyRecord.mother.mood === item" @change="updateDailyRadio(dailyRecord.mother,'mood',item)">{{ item }}</label></div></div><div class="form-field"><span class="field-label">乳房情况</span><div class="radio-row"><label v-for="item in ['正常','胀痛','硬块','红肿']" :key="item"><input type="radio" name="daily-mother-breast" :checked="dailyRecord.mother.breast === item" @change="updateDailyRadio(dailyRecord.mother,'breast',item)">{{ item }}</label></div></div><div class="form-field"><span class="field-label">恶露情况</span><div class="radio-row"><label v-for="item in ['少，无异味','中，无异味','多','有异味']" :key="item"><input type="radio" name="daily-mother-lochia" :checked="dailyRecord.mother.lochia === item" @change="updateDailyRadio(dailyRecord.mother,'lochia',item)">{{ item }}</label></div></div><div class="form-field"><span class="field-label">睡眠情况</span><div class="radio-row"><label v-for="item in ['好','中','差']" :key="item"><input type="radio" name="daily-mother-sleep" :checked="dailyRecord.mother.sleep === item" @change="updateDailyRadio(dailyRecord.mother,'sleep',item)">{{ item }}</label></div></div><div class="form-field"><span class="field-label">饮食情况</span><div class="radio-row"><label v-for="item in ['好','中','差']" :key="item"><input type="radio" name="daily-mother-diet" :checked="dailyRecord.mother.diet === item" @change="updateDailyRadio(dailyRecord.mother,'diet',item)">{{ item }}</label></div></div></div>
            <div v-else><div class="form-field"><span class="field-label">宝宝体温</span><input v-model="dailyRecord.baby.temperature" type="number" inputmode="decimal" placeholder="℃"></div><div class="form-field"><span class="field-label">体重</span><input v-model="dailyRecord.baby.weight" type="number" inputmode="decimal" placeholder="kg"></div><div class="form-field"><span class="field-label">黄疸变化</span><div class="radio-row"><label v-for="item in ['无','轻度消退','加重','待观察']" :key="item"><input type="radio" name="daily-baby-jaundice" :checked="dailyRecord.baby.jaundice === item" @change="updateDailyRadio(dailyRecord.baby,'jaundice',item)">{{ item }}</label></div></div><div class="form-field"><span class="field-label">皮肤状态</span><div class="radio-row"><label v-for="item in ['正常','皮疹','红臀','干燥']" :key="item"><input type="radio" name="daily-baby-skin" :checked="dailyRecord.baby.skin === item" @change="updateDailyRadio(dailyRecord.baby,'skin',item)">{{ item }}</label></div></div><div class="form-field"><span class="field-label">排便次数</span><input v-model="dailyRecord.baby.stoolCount" type="number" inputmode="numeric"></div><div class="form-field"><span class="field-label">睡眠时长</span><input v-model="dailyRecord.baby.sleepHours" type="number" inputmode="decimal" placeholder="小时"></div></div>
          </template></section>
          <section class="archive-card business-section daily-event-card"><div class="module-title"><i></i><strong>服务事件记录</strong><span>可多次新增</span></div><article v-for="item in events" :key="item.type"><strong>{{ item.type }}</strong><p>{{ item.text }}</p></article><button v-if="!readonlyDailyRecord" type="button">新增服务事件</button></section>
          <section v-if="dailyRecord.history.length" class="archive-card history-card"><div class="archive-head spaced"><strong>修改历史</strong><span>{{ dailyRecord.history.length }}条</span></div><article v-for="item in dailyRecord.history" :key="item.type + item.time"><strong>{{ item.type }}</strong><p>{{ item.operator }} · {{ item.time }}</p><span>{{ item.before }} → {{ item.after }}</span><em>{{ item.reason }}</em></article></section>
          <p v-if="dailyMessage" class="form-message">{{ dailyMessage }}</p><div v-if="!readonlyDailyRecord" class="archive-actions"><button type="button" @click="saveDailyDraft">保存</button><button type="button" @click="submitDailyRecord">发送到公司</button></div>
          <section v-if="dailyChangeDialogVisible" class="change-dialog-mask" @click.self="dailyChangeDialogVisible = false"><article class="change-dialog"><header><strong>申请修改</strong><button type="button" @click="dailyChangeDialogVisible = false">×</button></header><label>修改原因<textarea v-model="dailyChangeReason" rows="4" placeholder="例如：喂奶记录时间填写错误、护理备注需要补充"></textarea></label><footer><button type="button" @click="dailyChangeDialogVisible = false">取消</button><button type="button" @click="submitDailyChangeRequest">提交申请</button></footer></article></section>
          <section v-if="dailySendConfirmVisible" class="send-confirm-mask" @click.self="dailySendConfirmVisible = false"><article class="send-confirm"><strong>确认发送每日服务记录？</strong><p>发送后记录进入公司处理流程，暂不可直接修改。</p><footer><button type="button" @click="dailySendConfirmVisible = false">取消</button><button type="button" @click="confirmSendDailyRecord">确认发送</button></footer></article></section>
        </template>

        <template v-else-if="currentPage === 'history'"><button v-for="log in logs" :key="log.id" class="log-card" type="button"><div><strong>{{ log.date }}</strong><em class="tag ok">{{ log.status }}</em></div><p>宝宝出生{{ log.babyAge }}天 · 服务第{{ log.serviceDay }}天</p><span>{{ log.staff }} / {{ log.customer }}</span></button></template>
        <template v-else-if="currentPage === 'message'"><article v-for="item in messages" :key="item.text" class="message-card"><strong>{{ item.type }}</strong><span>{{ item.time }}</span><p>{{ item.text }}</p></article></template>

        <template v-else-if="currentPage === 'first'">
          <template v-if="firstArchiveView === 'list'">
            <section class="archive-order order-info-card"><div class="section-title"><strong>订单信息</strong></div><div class="inline-info arrival-order-info"><div><span>宝妈：</span><strong>{{ order.customer }}</strong></div><div><span>当前服务员：</span><strong>{{ order.staff }}</strong></div><div class="wide"><span>订单编号：</span><strong>{{ order.no }}</strong></div><div class="wide"><span>服务周期：</span><strong>{{ order.period }}</strong></div></div></section>
            <section class="archive-list arrival-record-list"><div class="section-title"><strong>到岗当日基础情况记录</strong><span>{{ firstArchives.length }}条</span></div><article v-for="(item,index) in firstArchives" :key="item.staff + item.arriveDate" class="archive-row arrival-record-row" @click="openArchive(index)"><div><strong>{{ item.staff }}</strong><p>到岗日期：{{ item.arriveDate }}</p></div><em :class="['tag', item.status === '待填写' || item.status === '草稿' ? 'draft' : item.status.includes('申请') ? 'pending' : 'ok']">{{ item.status }}</em><span class="row-arrow">›</span></article></section>
            <p v-if="firstArchiveMessage" class="form-message">{{ firstArchiveMessage }}</p>
          </template>

          <template v-else>
            <section v-if="activeArchive.status !== '待填写' && activeArchive.status !== '草稿'" class="record-status-tip">
              <div><strong>{{ activeArchive.status === '修改申请中' ? '审核中' : activeArchive.status === '可修改' ? '可修改' : activeArchive.status === '修改申请驳回' || activeArchive.status === '修改驳回' ? '修改申请驳回' : '已发送锁定' }}</strong><p v-if="activeArchive.status === '已发送' || activeArchive.status === '已提交'">记录已发送到公司，当前不可直接修改</p><p v-else-if="activeArchive.status === '修改申请中'">修改申请审核中，管理员审核前不可继续编辑</p><p v-else-if="activeArchive.status === '可修改'">管理员已通过修改申请，可重新编辑记录</p><p v-else>修改申请已驳回，记录保持锁定</p><span v-if="activeArchive.rejectReason">拒绝原因：{{ activeArchive.rejectReason }}</span></div>
              <button v-if="activeArchive.status === '已发送' || activeArchive.status === '已提交' || activeArchive.status === '修改申请驳回' || activeArchive.status === '修改驳回'" type="button" @click="openChangeDialog">申请修改</button>
              <div v-if="activeArchive.status === '修改申请中'" class="status-review-actions"><button type="button" @click="simulateApproveChange">通过</button><button type="button" @click="simulateRejectChange">拒绝</button></div>
            </section>
            <section class="archive-card business-section order-info-card"><div class="module-title"><i></i><strong>订单信息</strong></div><div class="inline-info arrival-order-info"><div><span>宝妈：</span><strong>{{ order.customer }}</strong></div><div><span>当前服务员：</span><strong>{{ activeArchive.staff }}</strong></div><div class="wide"><span>订单编号：</span><strong>{{ order.no }}</strong></div><div class="wide"><span>服务周期：</span><strong>{{ order.period }}</strong></div></div></section>
            <section class="archive-card business-section baby-section"><div class="module-title"><i></i><strong>宝宝信息</strong></div><div class="baby-count-block"><div class="sub-block-title"><strong class="required-title">宝宝数量</strong></div><div class="baby-count-field"><div v-if="readonlyArchive" class="read-value">{{ activeArchive.babyCountType }}{{ activeArchive.babyCountType === '多胎' ? ` · ${activeArchive.babies.length}` : '' }}</div><div v-else class="radio-row compact"><label v-for="item in ['单胎','多胎']" :key="item"><input type="radio" name="babyCount" :checked="activeArchive.babyCountType === item" @change="setBabyCount(item)">{{ item }}</label><label v-if="activeArchive.babyCountType === '多胎'" class="count-input">宝宝数量：<input :value="activeArchive.babies.length" type="number" min="2" max="5" @change="setBabyTotal($event.target.value)"></label></div></div></div><section v-for="(baby,index) in activeArchive.babies" :key="index" class="baby-panel baby-record"><div class="archive-head fold-head" @click="toggleBaby(index)"><strong>{{ activeArchive.babyCountType === '单胎' ? '宝宝' : `宝宝${index + 1}` }}</strong><span class="fold-state">{{ collapsedBabies[index] ? '展开' : '收起' }}</span></div><div class="fold-body" :class="{ collapsed: collapsedBabies[index] }">
              <template v-if="readonlyArchive"><div class="archive-read-grid"><p><span>宝宝姓名：</span><strong>{{ baby.name }}</strong></p><p><span>宝宝性别：</span><strong>{{ baby.gender }}</strong></p><p><span>出生日期：</span><strong>{{ baby.birthDate }}</strong></p><p><span>体温：</span><strong>{{ baby.temperature }}℃</strong></p><p><span>黄疸状态：</span><strong>{{ baby.jaundice }}</strong></p><p v-if="baby.jaundice === '有'"><span>黄疸值：</span><strong>{{ baby.jaundiceValue }}</strong></p><p v-if="baby.jaundice === '有'"><span>趋势：</span><strong>{{ baby.jaundiceTrend }}</strong></p><p><span>脐带状态：</span><strong>{{ baby.cord }}</strong></p><p v-if="baby.cord === '未脱落'"><span>分泌物：</span><strong>{{ baby.cordDischarge.join('、') }}</strong></p><p v-if="baby.cord === '未脱落'"><span>外观：</span><strong>{{ baby.cordAppearance.join('、') }}</strong></p><p><span>皮肤：</span><strong>{{ baby.skinType }}</strong></p><div class="archive-read-wide"><span>出院医嘱：</span><strong class="photo-list readonly"><span v-for="(photo, photoIndex) in baby.advicePhotos" :key="photo" class="photo-thumb" @click="openPhotoAction(baby, photoIndex)"></span></strong></div></div></template>
              <template v-else><div class="form-field"><span class="required">宝宝姓名</span><input v-model="baby.name"></div><div class="form-field"><span class="required">宝宝性别</span><div class="radio-row"><label v-for="item in ['男','女']" :key="item"><input type="radio" :name="`gender-${index}`" :checked="baby.gender === item" @change="updateRadio(baby,'gender',item)">{{ item }}</label></div></div><div class="form-field"><span class="required">出生日期</span><input v-model="baby.birthDate" type="date"></div><div class="form-field photo-field"><span class="field-label">出院医嘱</span><div class="photo-list"><span v-for="(photo, photoIndex) in baby.advicePhotos" :key="photo" class="photo-thumb" @click="openPhotoAction(baby, photoIndex)"></span><button type="button" @click="addAdvicePhoto(baby)">+ 添加图片</button></div></div><div class="form-field"><span class="field-label">体温</span><input v-model="baby.temperature" type="number" placeholder="℃"></div><div class="form-field"><span class="field-label">黄疸</span><div class="radio-row"><label v-for="item in ['无','有']" :key="item"><input type="radio" :name="`jaundice-${index}`" :checked="baby.jaundice === item" @change="updateRadio(baby,'jaundice',item)">{{ item }}</label></div></div><template v-if="baby.jaundice === '有'"><div class="sub-fields"><div class="inline-field"><span class="required">黄疸值</span><input v-model="baby.jaundiceValue" class="short-input" inputmode="decimal" pattern="[0-9.]*"></div><div class="stack-field"><span class="required">趋势</span><div class="radio-row compact"><label v-for="item in ['消退','加重']" :key="item"><input type="radio" :name="`jaundiceTrend-${index}`" :checked="baby.jaundiceTrend === item" @change="updateRadio(baby,'jaundiceTrend',item)">{{ item }}</label></div></div></div></template><div class="form-field"><span class="field-label">脐带</span><div class="radio-row"><label v-for="item in ['脱落','未脱落']" :key="item"><input type="radio" :name="`cord-${index}`" :checked="baby.cord === item" @change="updateRadio(baby,'cord',item)">{{ item }}</label></div></div><template v-if="baby.cord === '未脱落'"><div class="sub-fields"><div class="stack-field"><span class="required">分泌物</span><div class="check-row compact"><label v-for="item in ['无','渗性','脓性']" :key="item"><input type="checkbox" :checked="baby.cordDischarge.includes(item)" @change="updateCheckbox(baby,'cordDischarge',item,$event.target.checked)">{{ item }}</label></div></div><div class="stack-field"><span class="required">外观</span><div class="check-row compact"><label v-for="item in ['干燥','红肿','凸起']" :key="item"><input type="checkbox" :checked="baby.cordAppearance.includes(item)" @change="updateCheckbox(baby,'cordAppearance',item,$event.target.checked)">{{ item }}</label></div></div></div></template><div class="form-field"><span class="field-label">皮肤外观分类</span><div class="radio-row"><label v-for="item in ['正常','皮疹','胎记']" :key="item"><input type="radio" :name="`skin-${index}`" :checked="baby.skinType === item" @change="updateRadio(baby,'skinType',item)">{{ item }}</label></div></div></template></div></section></section>
            <section class="archive-card business-section mother-section"><div class="module-title fold-head" @click="toggleMother"><i></i><strong>宝妈信息</strong><span class="fold-state">{{ motherCollapsed ? '展开' : '收起' }}</span></div><div class="fold-body" :class="{ collapsed: motherCollapsed }"><template v-if="readonlyArchive"><div class="archive-read-grid"><p><span>体温：</span><strong>{{ activeArchive.mother.temperature }}℃</strong></p><p><span>乳房情况：</span><strong>{{ activeArchive.mother.breast }}</strong></p><p><span>乳头情况：</span><strong>{{ activeArchive.mother.nipple }}</strong></p><p><span>剖宫产伤口：</span><strong>{{ activeArchive.mother.cesareanWound }}</strong></p><p><span>恶露量：</span><strong>{{ activeArchive.mother.lochiaAmount }}</strong></p><p><span>恶露颜色：</span><strong>{{ activeArchive.mother.lochiaColor }}</strong></p><p><span>恶露气味：</span><strong>{{ activeArchive.mother.lochiaSmell }}</strong></p><div class="archive-read-wide"><span>现有疾病：</span><strong>{{ activeArchive.mother.diseases.join('、') }}</strong></div><div class="archive-read-wide"><span>现有传染病：</span><strong>{{ activeArchive.mother.infections.join('、') }}</strong></div><div class="archive-read-wide"><span>会阴伤口：</span><strong>{{ activeArchive.mother.perinealWound.join('、') }}</strong></div></div></template><template v-else><div class="form-field"><span class="field-label">体温</span><input v-model="activeArchive.mother.temperature" type="number" placeholder="℃"></div><div class="form-field"><span class="field-label">现有疾病</span><div class="check-row"><label v-for="item in ['无','高血压','糖尿病','乳腺炎','遗传疾病','其他']" :key="item"><input type="checkbox" :checked="activeArchive.mother.diseases.includes(item)" @change="updateCheckbox(activeArchive.mother,'diseases',item,$event.target.checked)">{{ item }}</label></div></div><div class="form-field"><span class="field-label">现有传染病</span><div class="check-row"><label v-for="item in ['无','乙肝','梅毒','其他']" :key="item"><input type="checkbox" :checked="activeArchive.mother.infections.includes(item)" @change="updateCheckbox(activeArchive.mother,'infections',item,$event.target.checked)">{{ item }}</label></div></div><div v-for="field in [{k:'breast',n:'乳房情况',o:['正常','硬块']},{k:'nipple',n:'乳头情况',o:['正常','凹陷','扁平']},{k:'cesareanWound',n:'剖宫产伤口',o:['正常','红肿','渗出','未知']},{k:'lochiaAmount',n:'恶露量',o:['多','中','少']},{k:'lochiaColor',n:'恶露颜色',o:['鲜红','暗红']},{k:'lochiaSmell',n:'恶露气味',o:['无异味','有异味']}]" :key="field.k" class="form-field"><span class="field-label">{{ field.n }}</span><div class="radio-row"><label v-for="item in field.o" :key="item"><input type="radio" :name="`mother-${field.k}`" :checked="activeArchive.mother[field.k] === item" @change="updateRadio(activeArchive.mother,field.k,item)">{{ item }}</label></div></div><div class="form-field"><span class="field-label">自然分娩会阴伤口</span><div class="check-row"><label v-for="item in ['侧切','撕裂','正常','红肿','渗出','未知']" :key="item"><input type="checkbox" :checked="activeArchive.mother.perinealWound.includes(item)" @change="updateCheckbox(activeArchive.mother,'perinealWound',item,$event.target.checked)">{{ item }}</label></div></div></template></div></section>
            <section v-if="activeArchive.history.length" class="archive-card history-card"><div class="archive-head spaced"><strong>修改历史</strong><span>{{ activeArchive.history.length }}条</span></div><article v-for="item in activeArchive.history" :key="item.type + item.time"><strong>{{ item.type }}</strong><p>{{ item.operator }} · {{ item.time }}</p><span>{{ item.before }} → {{ item.after }}</span><em>{{ item.reason }}</em></article></section>
            <p v-if="firstArchiveMessage" class="form-message">{{ firstArchiveMessage }}</p><div v-if="!readonlyArchive" class="archive-actions"><button type="button" @click="saveFirstDraft">保存</button><button type="button" :disabled="!canSubmitFirstArchive" @click="submitFirstArchive">发送到公司</button></div>
            <section v-if="changeDialogVisible" class="change-dialog-mask" @click.self="changeDialogVisible = false"><article class="change-dialog"><header><strong>申请修改</strong><button type="button" @click="changeDialogVisible = false">×</button></header><label>修改原因<textarea v-model="changeReason" rows="4" placeholder="例如：宝宝出生日期填写错误、黄疸值录入错误"></textarea></label><footer><button type="button" @click="changeDialogVisible = false">取消</button><button type="button" @click="submitChangeRequest">提交申请</button></footer></article></section>
            <section v-if="sendConfirmVisible" class="send-confirm-mask" @click.self="sendConfirmVisible = false"><article class="send-confirm"><strong>确认发送到岗当日基础情况记录？</strong><p>发送后记录进入公司处理流程，暂不可直接修改。</p><footer><button type="button" @click="sendConfirmVisible = false">取消</button><button type="button" @click="confirmSendFirstArchive">确认发送</button></footer></article></section>
